const body = $input.first().json.body;
const provider = body.provider;

if (!provider || !['google_drive', 'nextcloud', 'local'].includes(provider)) {
  return [{ json: { success: false, error: 'Provider must be google_drive, nextcloud, or local' } }];
}

return [{ json: { provider, url: body.url, username: body.username, password: body.password, client_id: body.client_id, client_secret: body.client_secret } }];

return [{
  json: {
    success: true,
    provider: 'google_drive',
    action_required: 'oauth',
    instructions: 'To connect Google Drive:\n1. Go to console.cloud.google.com\n2. Enable the Google Drive API\n3. Create OAuth 2.0 credentials (Desktop app type)\n4. Download the credentials JSON\n5. POST to /geivs/setup/storage with provider=google_drive, client_id and client_secret'
  }
}];

const input = $input.first().json;
const fs = require('fs');
const statePath = '/etc/geivs/geivs-state.json';

if (!input.url || !input.username || !input.password) {
  return [{ json: { success: false, error: 'Nextcloud requires url, username, and password' } }];
}

try {
  const state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
  state.integrations.nextcloud = {
    configured: true,
    url: input.url,
    username: input.username,
    password: input.password
  };
  fs.writeFileSync(statePath, JSON.stringify(state, null, 4));
  return [{ json: { success: true, message: 'Nextcloud configured at ' + input.url } }];
} catch(e) {
  return [{ json: { success: false, error: e.message } }];
}

const fs = require('fs');
const statePath = '/etc/geivs/geivs-state.json';

try {
  const state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
  state.integrations.local_storage = {
    configured: true,
    path: '/geivs/storage'
  };
  fs.writeFileSync(statePath, JSON.stringify(state, null, 4));
  return [{ json: { success: true, message: 'Local storage configured at /geivs/storage. You may place files there for GEIVS to access.' } }];
} catch(e) {
  return [{ json: { success: false, error: e.message } }];
}
